/**
 * Compile-time contract check between the hand-written request types and the backend's OpenAPI document
 * (`openapi.d.ts`, generated by `npm run api:types` from a running backend). If the backend changes a DTO in an
 * incompatible way, `npm run typecheck` fails here. Nothing in this file runs at runtime.
 */
import type { components } from './openapi';
import type { AssessmentInput, AssignmentInput, LessonInput, QuestionInput } from './endpoints';

type Schemas = components['schemas'];
type Assignable<From, To> = [From] extends [To] ? true : false;
type Expect<T extends true> = T;

export type ContractChecks = [
  Expect<Assignable<LessonInput, Schemas['CreateLessonDto']>>,
  Expect<Assignable<AssessmentInput, Schemas['CreateAssessmentDto']>>,
  Expect<Assignable<QuestionInput, Schemas['CreateQuestionDto']>>,
  Expect<Assignable<AssignmentInput, Schemas['CreateAssignmentDto']>>,
];

// Sanity: the check must be able to fail (a payload without the required `title` is NOT a valid lesson).
// @ts-expect-error -- `{}` is missing required fields of CreateLessonDto
export type MustFail = Expect<Assignable<Record<string, never>, Schemas['CreateLessonDto']>>;
